# Inspect the prompt result in a compact way, focusing on reference segmentation/object metadata.
if p.ok:
    out = p.output
    print("prompt keys", list(out.keys()))
    if "prompt_assets" in out:
        pa = out["prompt_assets"]
        print("asset keys", list(pa.keys()))
        if "scene" in pa:
            sc = pa["scene"]
            print("scene keys", list(sc.keys()))
            if "obj_info" in sc:
                print("obj_info", sc["obj_info"])
            if "segmentation_instances" in sc:
                print("prompt instances", sc["segmentation_instances"])
            if "segm" in sc:
                print("segm summary", sc["segm"])

q = call(
    name="observe_vima_prompt",
    agent_context={"need": "reference geometry"},
    prompt=None,
    query="Return the prompt reference scene's top-view segmentation instances, object ids, centers, bounding boxes, and identities compactly.",
)
if q.ok:
    qo = q.output
    print("query keys", list(qo.keys()))
    for k in ["prompt_asset_object_ids", "prompt_assets", "segmentation_instances", "obj_info", "scene"]:
        if k in qo:
            print(k, qo[k])

